let inputPollMs=0,inputPollSamples=0,maxInputPollMs=0;function sampleGamepadInput(updateStatus=true){const inputT0=performance.now();const g=getSelectedGamepad();if(g){if(gamepadRemapBit!==null){for(let i=0;i<g.buttons.length;i++)if(!g.buttons[i]?.pressed)captureIgnore.delete(i);for(let i=0;i<g.buttons.length;i++){if(g.buttons[i]?.pressed&&!captureIgnore.has(i)){gamepadConfig.map[gamepadRemapBit]=i;gamepadRemapBit=null;saveControlPrefs();renderControls();setStatus('Gamepad atualizado');break}}}let mask=0;for(let bit=0;bit<8;bit++){const i=Number(gamepadConfig.map[bit]);if(Number.isFinite(i)&&g.buttons[i]?.pressed)mask|=(1<<bit)}const dz=gamepadConfig.deadzone;if((g.axes[1]??0)<-dz)mask|=1<<4;if((g.axes[1]??0)>dz)mask|=1<<5;if((g.axes[0]??0)<-dz)mask|=1<<6;if((g.axes[0]??0)>dz)mask|=1<<7;bus.controller.setMask('gamepad',mask);const g2=getSecondGamepad();let mask2=0;if(g2){for(let bit=0;bit<8;bit++){const i=Number(defaultGamepadMap[bit]);if(Number.isFinite(i)&&g2.buttons[i]?.pressed)mask2|=(1<<bit)}const dz=gamepadConfig.deadzone;if((g2.axes[1]??0)<-dz)mask2|=1<<4;if((g2.axes[1]??0)>dz)mask2|=1<<5;if((g2.axes[0]??0)<-dz)mask2|=1<<6;if((g2.axes[0]??0)>dz)mask2|=1<<7}bus.controller2.setMask('gamepad',mask2);const gp3=getThirdGamepad(),gp4=getFourthGamepad();for(const [gp,ctrl] of [[gp3,bus.controller3],[gp4,bus.controller4]]){let m=0;if(gp){for(let bit=0;bit<8;bit++){const i=Number(defaultGamepadMap[bit]);if(Number.isFinite(i)&&gp.buttons[i]?.pressed)m|=(1<<bit)}const dz=gamepadConfig.deadzone;if((gp.axes[1]??0)<-dz)m|=1<<4;if((gp.axes[1]??0)>dz)m|=1<<5;if((gp.axes[0]??0)<-dz)m|=1<<6;if((gp.axes[0]??0)>dz)m|=1<<7}ctrl.setMask('gamepad',m)}if(updateStatus)document.querySelector('#gamepadStatus').textContent=`P1: ${g.id.slice(0,24)}${g2?` • P2: ${g2.id.slice(0,24)}`:''}${gp3?` • P3: ${gp3.id.slice(0,18)}`:''}${gp4?` • P4: ${gp4.id.slice(0,18)}`:''}`}else{bus.controller.clearSource('gamepad');bus.controller2.clearSource('gamepad');bus.controller3.clearSource('gamepad');bus.controller4.clearSource('gamepad')}const inputDt=performance.now()-inputT0;inputPollMs+=inputDt;inputPollSamples++;maxInputPollMs=Math.max(maxInputPollMs,inputDt)}
function gamepadPoll(){sampleGamepadInput(true);requestAnimationFrame(gamepadPoll)}gamepadPoll();


async function exportFullBackup(){const data={format:'NEO-NES-BACKUP',version:38,emulatorVersion:APP_VERSION,createdAt:Date.now(),storage:{},indexed:[]};for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&(k.startsWith('neo-nes-')||k.startsWith('nesstate'))){data.storage[k]=localStorage.getItem(k)}}try{data.indexed=(await stateStore.all()).filter(x=>x?.key)}catch{}const blob=new Blob([JSON.stringify(data,typedReplacer)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`neo-nes-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);setStatus(`Backup completo exportado (${data.indexed.length} saves binários)`)}
async function importFullBackup(file){const obj=JSON.parse(await file.text(),typedReviver);if(obj?.format!=='NEO-NES-BACKUP'||!obj.storage||typeof obj.storage!=='object')throw new Error('Backup NEO NES inválido');if(!confirm('Restaurar este backup? Configurações e saves com a mesma chave serão substituídos.'))return;let count=0;for(const [k,v] of Object.entries(obj.storage)){if((k.startsWith('neo-nes-')||k.startsWith('nesstate'))&&typeof v==='string'){localStorage.setItem(k,v);count++}}for(const rec of obj.indexed||[]){if(rec?.key){await idbPut('data',rec);count++}}loadSettings();loadControlPrefs(!!romHash);renderControls();renderSaveSlots();renderCheats();renderAchievements();updateHomeDashboard();setStatus(`Backup restaurado: ${count} itens`)}
document.querySelector('#exportBackupBtn').onclick=exportFullBackup;
document.querySelector('#importBackupInput').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{await importFullBackup(file)}catch(err){alert(err.message)}finally{e.target.value=''}};


function buildCrashReport(errorLike){const err=errorLike?.error||errorLike?.reason||errorLike;const message=err?.message||String(err||'Erro desconhecido');const stack=err?.stack||'';const report={format:'NEO-NES-CRASH-REPORT',version:1,emulatorVersion:APP_VERSION,timestamp:new Date().toISOString(),message,stack,rom:cart?{name:romDisplayName,hash:romHash,crc32:romCrc,mapper:cart.mapper,submapper:cart.submapper||0,region:cart.region||'NTSC'}:null,core:cart?{pc:bus.cpu.pc,a:bus.cpu.a,x:bus.cpu.x,y:bus.cpu.y,sp:bus.cpu.sp,cycles:bus.cpu.totalCycles,scanline:bus.ppu.scanline,dot:bus.ppu.cycle}:null,logs:logger.recent(40)};return JSON.stringify(report,null,2)}
function setupCrashReporting(){const copy=document.querySelector('#copyCrashBtn'),clear=document.querySelector('#clearCrashBtn'),out=document.querySelector('#crashOutput'),level=document.querySelector('#logLevelSelect');if(level){level.value=logger.level;level.onchange=()=>{logger.setLevel(level.value);setStatus(`Log: ${level.value}`)}}const refresh=()=>{if(out)out.textContent=lastCrashReport||'Nenhum crash registrado nesta sessão.'};window.addEventListener('error',e=>{lastCrashReport=buildCrashReport(e);logger.error('Erro global',{message:e.message,filename:e.filename,lineno:e.lineno});refresh()});window.addEventListener('unhandledrejection',e=>{lastCrashReport=buildCrashReport(e);logger.error('Promise rejeitada',{message:e.reason?.message||String(e.reason)});refresh()});if(copy)copy.onclick=async()=>{if(!lastCrashReport)return setStatus('Nenhum crash para copiar');try{await navigator.clipboard.writeText(lastCrashReport);setStatus('Relatório de crash copiado')}catch{setStatus('Não foi possível copiar')}};if(clear)clear.onclick=()=>{lastCrashReport='';refresh();setStatus('Relatório local limpo')};refresh()}
function showUpdateBanner(reg){const banner=document.querySelector('#updateBanner'),btn=document.querySelector('#updateNowBtn');if(!banner||!btn)return;banner.classList.remove('hidden');btn.onclick=()=>{const worker=reg.waiting;if(worker){worker.postMessage({type:'SKIP_WAITING'});btn.disabled=true;btn.textContent='Atualizando...'}else location.reload()}}
async function setupServiceWorkerUpdates(){if(!('serviceWorker'in navigator))return;try{const reg=await navigator.serviceWorker.register('./sw.js');if(reg.waiting&&navigator.serviceWorker.controller)showUpdateBanner(reg);reg.addEventListener('updatefound',()=>{const w=reg.installing;if(!w)return;w.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)showUpdateBanner(reg)})});let reloading=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(reloading)return;reloading=true;location.reload()});setInterval(()=>reg.update().catch(()=>{}),30*60*1000)}catch(e){logger.warn('Service Worker falhou',{message:e?.message})}}
async function runRuntimeSelfTest(){
 const out=document.querySelector('#selfTestOutput');if(!out)return;if(!cart){out.textContent='Carregue uma ROM antes do auto-teste.';return}
 const wasRunning=running;running=false;out.textContent='Executando auto-teste...';await new Promise(r=>setTimeout(r,0));
 let snap=null;const rows=[];try{
  snap=bus.snapshotBinary({});rows.push(['Save integrity',!!snap.integrity]);
  const before={pc:bus.cpu.pc,scan:bus.ppu.scanline,cycle:bus.ppu.cycle,hash:hashBytes(new Uint8Array(bus.ppu.image.buffer))};
  bus.controller.buttons=0xA5;bus.controller2.buttons=0x5A;bus.write(0x4016,1);bus.write(0x4016,0);const p1=bus.read(0x4016)&1,p2=bus.read(0x4017)&1;rows.push(['Controller ports',p1===(0xA5&1)&&p2===(0x5A&1)]);
  let guard=0;bus.ppu.frameComplete=false;while(!bus.ppu.frameComplete&&guard++<250000)bus.clock();rows.push(['Frame progress',!!bus.ppu.frameComplete&&guard<250000]);
  const afterHash=hashBytes(new Uint8Array(bus.ppu.image.buffer));rows.push(['Frame signature',afterHash.length===8]);
  bus.restore(snap);const restored=bus.cpu.pc===before.pc&&bus.ppu.scanline===before.scan&&bus.ppu.cycle===before.cycle;rows.push(['State round-trip',restored]);
  const ok=rows.every(x=>x[1]);out.textContent=rows.map(([n,v])=>`${v?'✅':'❌'} ${n}`).join('\n')+`\nFrame hash teste: ${afterHash}\nResultado: ${ok?'APROVADO':'VERIFICAR'}`;
 }catch(e){if(snap)try{bus.restore(snap)}catch{}out.textContent='❌ Auto-teste falhou: '+(e?.message||e)}finally{running=wasRunning}
}

const devPanel=document.querySelector('#devPanel'),devOutput=document.querySelector('#devOutput'),disasmOutput=document.querySelector('#disasmOutput'),memoryOutput=document.querySelector('#memoryOutput'),breakpointOutput=document.querySelector('#breakpointOutput');
function parseHexAddress(id){const raw=(document.querySelector(id)?.value||'').trim().replace(/^\$/,'').replace(/^0x/i,'');const addr=parseInt(raw,16);return Number.isFinite(addr)?addr&65535:null}
function refreshDevPanel(){if(!devPanel||devPanel.classList.contains('hidden'))return;if(!cart){devOutput.textContent='Carregue uma ROM para usar o Dev Mode.';disasmOutput.textContent='';memoryOutput.textContent='';breakpointOutput.textContent='Breakpoints: —';return}devOutput.textContent=debuggerCore.stateText();disasmOutput.textContent=debuggerCore.disassemble(bus.cpu.pc,16);const ma=parseHexAddress('#memoryAddress')??0;memoryOutput.textContent=`Memory $${ma.toString(16).padStart(4,'0').toUpperCase()}\n`+debuggerCore.memoryDump(ma,256);breakpointOutput.textContent=debuggerCore.breakpointText()}
function pauseForDebug(){running=false;document.querySelector('#pauseBtn').textContent='Continuar';refreshDevPanel();present()}
document.querySelector('#devModeToggle')?.addEventListener('change',e=>{debuggerCore.setEnabled(e.target.checked);devPanel.classList.toggle('hidden',!e.target.checked);localStorage.setItem('neo-nes-dev-mode',e.target.checked?'1':'0');refreshDevPanel()});
