document.querySelector('#stepInstructionBtn')?.addEventListener('click',()=>{if(!cart)return;pauseForDebug();debuggerCore.stepInstruction();refreshDevPanel();present()});
document.querySelector('#stepScanlineBtn')?.addEventListener('click',()=>{if(!cart)return;pauseForDebug();debuggerCore.stepScanline();refreshDevPanel();present()});
document.querySelector('#stepFrameBtn')?.addEventListener('click',()=>{if(!cart)return;pauseForDebug();debuggerCore.stepFrame();refreshDevPanel();present()});
document.querySelector('#addBreakpointBtn')?.addEventListener('click',()=>{const addr=parseHexAddress('#breakpointPc');if(addr==null){setStatus('Breakpoint inválido');return}const type=document.querySelector('#breakpointType')?.value||'exec';debuggerCore.addBreakpoint(type,addr);debuggerCore.clearBreakRequest();setStatus(`${type.toUpperCase()} breakpoint em $${addr.toString(16).padStart(4,'0').toUpperCase()}`);refreshDevPanel()});
document.querySelector('#clearBreakpointsBtn')?.addEventListener('click',()=>{debuggerCore.clearBreakpoints();setStatus('Breakpoints removidos');refreshDevPanel()});
for(const [id,type] of [['breakNmiToggle','nmi'],['breakIrqToggle','irq'],['breakSprite0Toggle','sprite0']])document.querySelector('#'+id)?.addEventListener('change',e=>{debuggerCore.setEventBreakpoint(type,e.target.checked);refreshDevPanel()});
