document.querySelector('#runToPcBtn')?.addEventListener('click',()=>{if(!cart)return;const addr=parseHexAddress('#breakpointPc');if(addr==null){setStatus('Breakpoint inválido');return}pauseForDebug();debuggerCore.clearBreakRequest();let n=0;while((bus.cpu.pc&65535)!==addr&&n<200000){if(!debuggerCore.stepInstruction())break;n++}setStatus((bus.cpu.pc&65535)===addr?`PC atingido em $${addr.toString(16).padStart(4,'0').toUpperCase()}`:'Endereço não atingido no limite de segurança');refreshDevPanel();present()});
document.querySelector('#traceToggle')?.addEventListener('change',e=>{debuggerCore.setTrace(e.target.checked);setStatus(e.target.checked?'Trace logger ativado':'Trace logger desativado')});
document.querySelector('#clearTraceBtn')?.addEventListener('click',()=>{debuggerCore.clearTrace();setStatus('Trace limpo')});
document.querySelector('#exportTraceBtn')?.addEventListener('click',()=>{const text=debuggerCore.traceText(4096);if(!text){setStatus('Trace vazio');return}const blob=new Blob([text],{type:'text/plain'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`neo-nes-trace-${romCrc||'rom'}-${Date.now()}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);setStatus('Trace exportado')});
document.querySelector('#refreshMemoryBtn')?.addEventListener('click',refreshDevPanel);
document.querySelector('#memoryAddress')?.addEventListener('change',refreshDevPanel);
