function syncInputDeviceUi(){
  const fs=document.querySelector('#fourScoreToggle'),p2=document.querySelector('#port2Device'),touch=document.querySelector('#touchControls');
  if(fs)fs.checked=bus.input.fourScore.enabled;if(p2)p2.value=bus.input.port2Device;
  if(touch){touch.style.setProperty('--touch-scale',String(touchScale));touch.style.setProperty('--touch-opacity',String(touchOpacity))}
  const sr=document.querySelector('#touchScaleRange'),or=document.querySelector('#touchOpacityRange'),ht=document.querySelector('#touchHapticsToggle');if(sr){sr.value=Math.round(touchScale*100);document.querySelector('#touchScaleValue').textContent=sr.value+'%'}if(or){or.value=Math.round(touchOpacity*100);document.querySelector('#touchOpacityValue').textContent=or.value+'%'}if(ht)ht.checked=touchHaptics;
  document.body.classList.toggle('zapper-active',bus.input.port2Device==='zapper');
}
function setupInputDevices(){
  const fs=document.querySelector('#fourScoreToggle'),p2=document.querySelector('#port2Device');
  if(fs)fs.onchange=e=>{bus.input.fourScore.setEnabled(e.target.checked);if(e.target.checked&&bus.input.port2Device==='zapper'){bus.input.setPort2Device('controller');if(p2)p2.value='controller'}saveSettings();setStatus(e.target.checked?'Four Score ativo: até 4 jogadores':'Four Score desligado')};
  if(p2)p2.onchange=e=>{if(e.target.value==='zapper'&&bus.input.fourScore.enabled){bus.input.fourScore.setEnabled(false);if(fs)fs.checked=false}bus.input.setPort2Device(e.target.value);syncInputDeviceUi();saveSettings();setStatus(e.target.value==='zapper'?'Zapper ativo: mire e clique na tela':'Controle padrão na porta 2')};
  const sr=document.querySelector('#touchScaleRange'),or=document.querySelector('#touchOpacityRange'),ht=document.querySelector('#touchHapticsToggle');
  if(sr)sr.oninput=e=>{touchScale=Number(e.target.value)/100;syncInputDeviceUi();saveSettings()};if(or)or.oninput=e=>{touchOpacity=Number(e.target.value)/100;syncInputDeviceUi();saveSettings()};if(ht)ht.onchange=e=>{touchHaptics=e.target.checked;saveSettings()};
  const wrap=document.querySelector('.screen-wrap');const aim=e=>{if(bus.input.port2Device!=='zapper')return;const target=gpuCanvas.style.display!=='none'?gpuCanvas:canvas,r=target.getBoundingClientRect();if(!r.width||!r.height)return;const c=activeOverscan(),sw=256-c.left-c.right,sh=240-c.top-c.bottom;bus.input.zapper.aim(c.left+((e.clientX-r.left)/r.width)*sw,c.top+((e.clientY-r.top)/r.height)*sh)};
  wrap?.addEventListener('pointermove',aim,{passive:true});wrap?.addEventListener('pointerdown',e=>{if(bus.input.port2Device!=='zapper')return;e.preventDefault();aim(e);bus.input.zapper.setTrigger(true);navigator.vibrate?.(12)},{passive:false});for(const ev of ['pointerup','pointercancel','pointerleave'])wrap?.addEventListener(ev,()=>bus.input.zapper.setTrigger(false),{passive:true});
  syncInputDeviceUi();
}

